INSERT INTO asset_import_batch(
    id, file_name, imported_by, imported_at, created_count, updated_count, skipped_count, error_detail, create_time
) VALUES (
    #{id}, #{fileName}, #{importedBy}, #{importedAt}, #{createdCount}, #{updatedCount}, #{skippedCount}, #{errorDetail}, #{createTime}
)
ON DUPLICATE KEY UPDATE
    created_count = VALUES(created_count),
    updated_count = VALUES(updated_count),
    skipped_count = VALUES(skipped_count),
    error_detail = VALUES(error_detail)

