UPDATE asset_record_value
SET column_value =


        #{replace}


        CONCAT(#{replace}, SUBSTRING(column_value, CHAR_LENGTH(#{search}) + 1))


        REPLACE(column_value, #{search}, #{replace})


WHERE column_key = #{columnKey}


        AND column_value = #{search}


        AND column_value LIKE CONCAT(#{search}, '%') ESCAPE '\\'


        AND column_value LIKE CONCAT('%', #{search}, '%') ESCAPE '\\'
